  ('banh-mi-trung', 'banh-mi', 100),
  ('banh-mi-trung', 'trung-ga', 100),
  ('banh-mi-trung', 'dua-leo', 30),
  ('banh-mi-trung', 'dau-an', 5),
  ('banh-mi-trung', 'nuoc-mam', 3),
