  ('bun-cha', 'nuoc-mam', 10),
  ('bun-cha', 'duong-trang', 5),
  ('bun-cha', 'toi', 5),
  ('bun-cha', 'dau-an', 5)
)
select d.id, i.id, s.grams
from component_seed s
join public.foods d on d.slug = s.dish_slug
join public.foods i on i.slug = s.ingredient_slug
on conflict (dish_id, ingredient_id) do update set grams = excluded.grams;

-- 3b. Món cũ đã bị món trong bảng VDD thay: bỏ thành phần cũ để không bị tính lại đè lên số VDD.
delete from public.dish_components
where dish_id in (select id from public.foods where slug in ('bun-bo-hue', 'rau-muong-xao-toi', 'dau-hu-sot-ca-chua', 'goi-cuon-tom-thit', 'ca-basa-kho-to'));

-- 4. Tính lại chỉ số của món từ thành phần vừa nạp.
--    Bước này khiến CSDL trở thành nguồn chân lý: dù file trên có sai sót,
--    con số cuối cùng vẫn nhất quán với thành phần.
select public.recompute_dish_nutrients(id) from public.foods where kind = 'dish';

-- 5. Danh mục bài tập
--    MET là nguồn chân lý để tính kcal đốt của buổi tập; không được để model tự đoán.
on conflict (slug) do update set
    name_vi = excluded.name_vi,
    muscle_group = excluded.muscle_group,
    equipment = excluded.equipment,
    level = excluded.level,
    measure = excluded.measure,
    met = excluded.met,
    contraindications = excluded.contraindications,
    cue = excluded.cue,
    source_ref = excluded.source_ref
;
